CREATE OR REPLACE FUNCTION erp.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_reason text := nullif(current_setting('app.change_reason', true), '');
  v_old jsonb;
  v_new jsonb;
  v_key jsonb;
  v_id_text text;
  v_entity_id uuid;
begin
  if tg_op <> 'INSERT' then v_old := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_new := to_jsonb(new); end if;
  v_key := coalesce(v_new, v_old);
  v_id_text := coalesce(nullif(v_key->>'id', ''), nullif(v_key->>'material_id', ''));
  if v_id_text is not null then
    begin
      v_entity_id := v_id_text::uuid;
    exception when invalid_text_representation then
      v_entity_id := null;
    end;
  end if;

  if tg_op = 'INSERT' then
    insert into erp.audit_logs(
      entity_type, entity_id, action, new_data, changed_by, change_reason
    ) values (
      tg_table_name, v_entity_id, 'INSERT', v_new,
      erp.current_app_user_id(), v_reason
    );
    return new;
  elsif tg_op = 'UPDATE' then
    if v_old is distinct from v_new then
      insert into erp.audit_logs(
        entity_type, entity_id, action, old_data, new_data, changed_by, change_reason
      ) values (
        tg_table_name, v_entity_id, 'UPDATE', v_old, v_new,
        erp.current_app_user_id(), v_reason
      );
    end if;
    return new;
  else
    insert into erp.audit_logs(
      entity_type, entity_id, action, old_data, changed_by, change_reason
    ) values (
      tg_table_name, v_entity_id, 'DELETE', v_old,
      erp.current_app_user_id(), v_reason
    );
    return old;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION erp.bb_guard_open_sales_draft_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d erp.bb_open_sales_drafts_v1%rowtype;
begin
  select * into d from erp.bb_open_sales_drafts_v1 where sale_id=old.id;
  if d.sale_id is null then return case when tg_op='DELETE' then old else new end;end if;
  if tg_op='DELETE' then raise exception 'BB_S02_DRAFT_KEPT: draf penjualan dari saldo awal tidak dapat dihapus; batalkan lewat halaman penjualan';end if;
  if new.sale_number is distinct from old.sale_number or new.customer_id is distinct from old.customer_id then
    raise exception 'BB_S02_IDENTITY: nomor dan pelanggan draf penjualan dari saldo awal tidak dapat diubah';
  end if;
  if new.sale_date<d.cutover_at then
    raise exception 'BB_S02_DATE_BEFORE_CUTOVER: tanggal invoice draf dari saldo awal tidak boleh sebelum saldo awal';
  end if;
  return new;
end;$function$

