  if new.physical_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'Tanggal/jam fisik % berada di masa depan. Periksa tanggal/jam transaksi sebelum posting.',new.physical_at;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION erp.guard_posted_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
BEGIN
  IF current_user IN ('postgres','service_role','supabase_admin') THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  -- Ordinary header writes already hold the row lock. Server RPCs above use
  -- release/rebuild or cancellation atomically under that same header lock.
  IF TG_TABLE_NAME='sales_headers' AND TG_OP IN('UPDATE','DELETE') THEN
    IF TG_OP='DELETE' OR
       (to_jsonb(NEW)->'id',to_jsonb(NEW)->'customer_id',to_jsonb(NEW)->'source_location_id',to_jsonb(NEW)->'sale_date')
       IS DISTINCT FROM
       (to_jsonb(OLD)->'id',to_jsonb(OLD)->'customer_id',to_jsonb(OLD)->'source_location_id',to_jsonb(OLD)->'sale_date') THEN
      IF EXISTS(SELECT 1 FROM erp.sale_stock_allocations a JOIN erp.sales_items i ON i.id=a.sale_item_id WHERE i.sale_id=OLD.id)
         OR EXISTS(SELECT 1 FROM erp.fg_stock_movements m JOIN erp.sales_items i ON i.id=m.source_id
           WHERE i.sale_id=OLD.id AND m.source_type='SALE_ITEM' AND m.movement_type IN('SALE_RESERVE','SALE')
             AND NOT EXISTS(SELECT 1 FROM erp.fg_stock_movements rv WHERE rv.reversal_of_id=m.id)) THEN
        RAISE EXCEPTION 'AG_RESERVED_SALE_EDIT_REQUIRES_SAVE_RPC: use save_sale_draft_v2 or cancel_sale_draft_v2';
      END IF;
    END IF;
  END IF;

  IF TG_OP='INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'Document must be created as DRAFT; use the ERP posting RPC to post it';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP='DELETE' THEN
    IF OLD.status<>'DRAFT' THEN
      RAISE EXCEPTION 'Posted/non-draft document cannot be deleted directly; use reversal/correction';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status<>'DRAFT' THEN
    RAISE EXCEPTION 'Posted/non-draft document cannot be edited directly; use reversal/correction';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'Document status cannot leave DRAFT by direct table update; use the ERP posting/cancellation RPC';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION erp.guard_sales_payment_posted_identity_v2620j()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
AS $function$
begin
  if tg_op='INSERT' then
    if new.status<>'DRAFT' then
      raise exception using errcode='42501',message='PAYMENT_MUST_START_DRAFT';
    end if;
    return new;
  end if;
  if tg_op='DELETE' then
    if old.status<>'DRAFT' then
      raise exception using errcode='42501',message='POSTED_PAYMENT_IDENTITY_IMMUTABLE';
    end if;
    return old;
  end if;
  if old.status='DRAFT' and new.status='DRAFT' then return new; end if;
  if old.status='DRAFT' and new.status='POSTED'
     and (pg_catalog.to_jsonb(new)-'status') is not distinct from
       (pg_catalog.to_jsonb(old)-'status')
     and exists(
       select 1 from erp.sales_payment_posting_facts f
       where f.payment_id=new.id
         and f.payment_snapshot=pg_catalog.to_jsonb(new)-'status'
     ) then
    return new;
  end if;
  if old.status='POSTED' and new.status='REVERSED'
     and (pg_catalog.to_jsonb(new)-'status') is not distinct from
       (pg_catalog.to_jsonb(old)-'status')
     and exists(select 1 from erp.sales_payment_reversal_facts r where r.payment_id=new.id) then
    return new;
  end if;
  raise exception using errcode='42501',
    message='POSTED_PAYMENT_IDENTITY_IMMUTABLE: reverse and post one linked replacement';
end
$function$

CREATE OR REPLACE FUNCTION erp.guard_sales_return_physical_date()
 RETURNS trigger
 LANGUAGE plpgsql
